    explanation: '民法第446条第1項は、保証人は、主たる債務者がその債務を履行しないときに、その履行をする責任を負うと定める。保証契約は書面でしなければ効力を生じない（同条第2項、要式契約）。単純保証人には催告の抗弁権・検索の抗弁権が認められるが（第452条・第453条）、連帯保証人にはこれらが認められない（第454条）点が重要な相違点である。保証債務は主たる債務への付従性を有する。\n\n【図解】保証債務の性質\n　性質｜内容｜根拠\n　要式性｜書面または電磁的記録でしなければ効力を生じない｜民法446条2項\n　付従性｜主たる債務が消滅すれば保証債務も消滅する｜性質上の帰結\n　補充性｜催告の抗弁と検索の抗弁がある｜民法452条・453条\n　⇒ 連帯保証には補充性がなく、両抗弁を持ちません\n　⚠ 個人が事業用融資の保証をするには公正証書による意思表示が必要です。',
