    explanation: '民法第915条第1項は、相続人は、自己のために相続の開始があったことを知った時から3か月以内（熟慮期間）に、単純承認・限定承認・相続放棄のいずれかを選択しなければならないと定める。相続放棄をした者は初めから相続人とならなかったものとみなされる（第939条）が、現に占有する財産については一定の保存義務が及ぶ場合がある（第940条）。区分所有権付きマンションの相続を巡る実務でも重要な期間制限である。\n\n【図解】相続の3つの選択肢\n　選択｜内容｜手続\n　単純承認｜権利義務をすべて承継する｜手続不要（法定単純承認もある）\n　限定承認｜相続財産の限度で債務を弁済する｜相続人全員で家庭裁判所に申述\n　相続放棄｜初めから相続人でなかったとみなす｜各自が家庭裁判所に申述\n　⇒ いずれも自己のために相続の開始を知った時から3か月以内に行います\n　⚠ 相続財産を処分すると法定単純承認となります（民法921条）。',
