    explanation: '民法第192条は、動産の即時取得（善意取得）について、取引行為によって平穏かつ公然と動産の占有を始めた者は、善意無過失であれば即時にその動産についての権利を取得すると定める。この制度は動産取引の安全を保護するものであり、不動産には適用されない（不動産は登記制度により公示される）。盗品・遺失物については、被害者等の回復請求権が一定期間認められる（第193条）。\n\n【図解】即時取得の要件\n　要件｜内容｜備考\n　動産であること｜不動産には適用がない｜民法192条\n　取引行為による取得｜相続などでは成立しない｜民法192条\n　平穏・公然・善意・無過失｜占有開始の時に判断する｜前三者は推定される\n　⇒ 占有改定による引渡しでは即時取得は成立しません（判例）\n　⚠ 盗品や遺失物は2年間の回復請求が認められます（民法193条）。',
