    correctKey: 'B',
    explanation: '民法第127条第1項は、停止条件付法律行為は、停止条件が成就した時から効力を生ずると定め、同条第2項は、解除条件付法律行為は、解除条件が成就した時から効力を失うと定める。期限の利益は、原則として債務者のためにあると推定される（第136条第1項）。マンションの契約（工事請負契約の出来高払い等）における条件・期限の理解の基礎となる規定である。\n\n【図解】条件と期限の違い\n　概念｜内容｜効果\n　停止条件｜成就により効力が生じる｜成就の時から効力が発生（民法127条1項）\n　解除条件｜成就により効力が失われる｜成就の時から効力が消滅（127条2項）\n　期限｜到来することが確実な事実｜期限の利益は放棄できる（136条2項）\n　⇒ 条件の成就を故意に妨げた者に対しては成就したものとみなせます\n　⚠ 不法な条件を付した法律行為は無効です（民法132条）。',
