    correctKey: 'B',
    explanation: '相続人のあることが明らかでない場合、相続財産は法人とされ（第951条）、家庭裁判所は利害関係人の請求により相続財産清算人を選任する（第952条第1項）。所有者不明の専有部分について滞納管理費を有する管理組合は、この利害関係人（債権者）として清算人の選任を申し立て、相続財産（区分所有権）からの回収を図ることができる。令和3年民法改正により、この制度の手続（公告期間の統合等）が合理化された。\n\n【図解】相続人が不存在の場合の手続\n　段階｜内容｜根拠\n　相続財産清算人の選任｜利害関係人等の請求により選任される｜民法952条\n　公告｜相続人の捜索と債権申出の公告を行う｜民法952条2項\n　特別縁故者への分与｜請求により財産の全部または一部を分与する｜民法958条の2\n　⇒ 最終的に残った財産は国庫に帰属します（民法959条）\n　⚠ 令和3年改正で相続財産管理人から相続財産清算人へ改められました。',
