    correctKey: 'C',
    explanation: '令和3年民法改正により新設された所有者不明土地・建物管理制度（第264条の2以下）は、所有者不明の不動産について、地方裁判所が、利害関係人の請求により、管理人による管理を命ずる処分をすることができる制度である（相続財産清算人が家庭裁判所の管轄であるのと対照的）。区分所有建物の専有部分にこの制度を適用する場合には、区分所有法との関係（他の区分所有者・敷地利用権への配慮等）について特則が置かれている（区分所有法第6条第4項等）。\n\n【図解】所有者不明の場合の管理制度\n　制度｜対象｜根拠\n　所有者不明土地管理命令｜所有者やその所在を知ることができない土地｜民法264条の2\n　所有者不明建物管理命令｜同様の建物｜民法264条の8\n　管理人の権限｜保存および利用改良行為｜これを超えるには裁判所の許可\n　⇒ 令和3年改正で新設され、令和5年から施行されています\n　⚠ 区分所有建物の専有部分には適用が制限される点に注意が必要です。',
