    correctKey: 'D',
    explanation: '民法第887条第2項は、被相続人の子が相続開始以前に死亡したとき、又は相続欠格・廃除によって相続権を失ったときは、その者の子（被相続人の孫等）が代襲して相続人となると定める。代襲原因は死亡・欠格・廃除に限られ、相続放棄は含まれない点に注意する。兄弟姉妹が相続人となる場合にも代襲相続は準用されるが、再代襲（甥・姪の子への代襲）は生じない（第889条第2項が第887条第3項を準用しない）。区分所有権の相続関係の整理において重要な規律である。\n\n【図解】代襲相続の範囲\n　被代襲者｜代襲の原因｜再代襲の可否\n　子｜死亡・相続欠格・廃除｜孫やひ孫まで認められる\n　兄弟姉妹｜死亡・相続欠格・廃除｜甥や姪まで一代限り\n　⇒ 相続放棄は代襲原因になりません\n　⚠ 兄弟姉妹の代襲は一代限りで、再代襲は認められません。',
    difficulty: 'advanced',
