    correctKey: 'B',
    explanation: '所有者不明土地問題への対応の一環として、令和6年4月1日施行の改正不動産登記法により、相続による不動産（区分所有権を含む）の取得を知った日から3年以内に相続登記を申請することが義務付けられた。正当な理由なくこの申請を怠ると、10万円以下の過料の対象となり得る。マンションの相続を巡る所有者不明化の防止に資する重要な制度改正であり、管理組合の名簿管理の観点からも意義がある。\n\n【図解】相続登記の申請義務\n　項目｜内容｜根拠\n　義務の内容｜所有権の取得を知った日から3年以内に申請する｜不動産登記法76条の2\n　施行｜令和6年4月から（過去の相続にも適用）｜経過措置がある\n　相続人申告登記｜簡易に義務を履行できる制度｜不動産登記法76条の3\n　⇒ 正当な理由なく怠ると10万円以下の過料の対象となります\n　⚠ 施行日前に発生した相続にも適用される点に注意が必要です。',
