    correctKey: 'B',
    explanation: '民法第98条第1項は、表意者が相手方を知ることができず、又はその所在を知ることができないときは、公示の方法（裁判所の掲示場への掲示、官報への掲載等）によって意思表示をすることができると定める。区分所有法上、区分所有者の所在が不明な場合の招集通知に関しては、建物内の見やすい場所への掲示（区分所有法第35条第4項）という別途の簡易な仕組みが用意されているが、より一般的な相手方不明の意思表示の場面では、この民法の公示による意思表示の制度が参考になる。\n\n【図解】公示による意思表示\n　場面｜申立先｜根拠\n　相手方を知ることができない｜表意者の住所地の簡易裁判所｜民法98条4項\n　相手方の所在を知ることができない｜相手方の最後の住所地の簡易裁判所｜民法98条4項\n　効力の発生｜掲示を始めた日から2週間の経過で到達とみなす｜民法98条3項\n　⇒ 官報に少なくとも1回掲載する方法により行います\n　⚠ 表意者に過失があるときは到達の効力を生じません。',
