    correctKey: 'B',
    explanation: '民法第645条は、受任者は、委任者の請求があるときはいつでも委任事務処理の状況を報告し、委任終了後は遅滞なくその経過及び結果を報告しなければならないと定める。マンション管理適正化法第77条が定めるマンション管理業者の管理事務報告義務は、この民法上の受任者の報告義務の考え方を基礎としつつ、より具体的な内容（管理業務主任者による記名、定期の報告等）を法律上義務付けたものと理解することができ、両者の関連性を意識した学習が有用である。\n\n【図解】受任者の報告義務\n　場面｜内容｜根拠\n　委任者の請求があるとき｜いつでも処理の状況を報告する｜民法645条\n　委任の終了後｜遅滞なく経過と結果を報告する｜民法645条\n　受け取った物がある場合｜委任者に引き渡す｜民法646条1項\n　⇒ 管理業者による管理事務の報告もこの考え方に対応します\n　⚠ 報告義務は特約がなくても当然に生じます。',
    difficulty: 'advanced',
